def test_average_over_a_variant_branch_stays_refused() -> None:
    expression = 'CALCULATE(ISDOUBLE(IF(COUNTROWS(Facts)>2,CURRENCY(3),AVERAGEX(ADDCOLUMNS(Facts,"v",COALESCE(MAX(Facts[Note]),0)),[v]))),REMOVEFILTERS(Facts[Region]))'
    assert local(expression).startswith("LOCAL-")


def test_text_fallback_iferror_variant_stays_refused() -> None:
    expression = 'CALCULATE(ISDOUBLE(IF(SUM(Facts[Quantity])>3,COUNTROWS(Facts),MAXX(ADDCOLUMNS(VALUES(Facts[Region]),"v",IFERROR(1/SUM(Facts[Quantity]),"d0")),[v]))),ALL(Facts))'
    assert local(expression).startswith("LOCAL-")


def test_this_file_holds_enough_shapes() -> None:
    assert len(ANSWERED) == 135
    assert len(ANSWERED_SECOND) == 135
    assert len(ANSWERED_THIRD) == 135
    assert len(ANSWERED_FOURTH) == 135
    assert len(STILL_REFUSED) == 35
    assert len(STILL_REFUSED_SECOND) == 35
    assert len(STILL_REFUSED_THIRD) == 35
    assert len(STILL_REFUSED_FOURTH) == 35
